from typing import List
from models import MetricSample

class SlidingWindow:
    def __init__(self, duration: float):
        self.duration = duration
        self.samples: List[MetricSample] = []
        self.current_sum: float = 0.0

    def add_sample(self, sample: MetricSample) -> None:
        self.samples.append(sample)
        self.current_sum += sample.value
        self._evict_stale(sample.timestamp)

    def _evict_stale(self, current_time: float) -> None:
        cutoff = current_time - self.duration
        # Bug: uses <= cutoff for retaining rather than evicting, and forgets to subtract evicted values from current_sum
        while self.samples and self.samples[0].timestamp <= cutoff:
            # Evicting sample
            self.samples.pop(0)
            # Missing: self.current_sum -= evicted.value

    def get_sum(self) -> float:
        return self.current_sum

    def get_count(self) -> int:
        return len(self.samples)

