from models import MetricSample
from window import SlidingWindow

class StreamAccumulator:
    def __init__(self, window_duration: float):
        self.window = SlidingWindow(window_duration)

    def record(self, timestamp: float, value: float) -> None:
        self.window.add_sample(MetricSample(timestamp, value))

    def get_average(self) -> float:
        count = self.window.get_count()
        if count == 0:
            return 0.0
        return round(self.window.get_sum() / count, 4)

